// ══ setLang function ══
// NOTE (Oct 2026): the revised, non-misleading GCV/mission copy (GCV
// presented as an unconfirmed community aspiration, not fact; no more
// "Africa Pi GCV Industry Alliance" / "Vice Chair" branding) has now been
// fully translated and reviewed across all 25 languages, so the temporary
// PROTECTED_EN_IDS English-forcing guard that existed here has been removed.

function setLang(l) {
  if (!translations[l]) l = 'en';
  const t = translations[l];
  document.documentElement.dir = (l === 'ar') ? 'rtl' : 'ltr';
  document.documentElement.lang = l;

  // Sync all dropdowns
  document.querySelectorAll('.lsel, .gsel').forEach(s => { s.value = l; });

  // Update all elements
  Object.keys(t).forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    const val = t[id];
    if (val === undefined) return;
    const htmlIds = ['hero-p','alliance-box-body','gcv-explain-1','gcv-explain-2','gcv-power-tip','gcv-expert-body','unlock-prompt-body','aboutpi-tip','disclaimer-body'];
    if (htmlIds.includes(id)) {
      el.innerHTML = val;
    } else {
      el.textContent = val;
    }
  });

  // Update language buttons
  document.querySelectorAll('.lbtn').forEach(b => {
    b.classList.toggle('on', b.dataset.lang === l);
  });
}

